# Hashti — Unified Test Runner
# Run from project root: powershell -ExecutionPolicy Bypass -File .\test-hashti-all.ps1
# Phases: isolated business integration, API/session/authorization smoke tests, final preflight audit.
# The original amlak database is used only by the existing safe read/reversible API checks.
# Write-heavy business workflow tests use a uniquely named temporary database.

$ErrorActionPreference = 'Continue'
$root = (Get-Location).Path
if (-not (Test-Path (Join-Path $root 'docker-compose.yml')) -and -not (Test-Path (Join-Path $root 'compose.yml'))) {
  Write-Host 'خطا: اسکریپت را از پوشه اصلی پروژه، کنار docker-compose.yml اجرا کن.' -ForegroundColor Red
  exit 2
}

$script:PhaseResults = @()
$tempRoot = Join-Path $env:TEMP ('hashti-unified-tests-' + [Guid]::NewGuid().ToString('N'))
New-Item -ItemType Directory -Path $tempRoot -Force | Out-Null

function Run-Phase {
  param([string]$Title, [string]$FilePath)
  Write-Host "`n============================================================" -ForegroundColor Cyan
  Write-Host "مرحله: $Title" -ForegroundColor Cyan
  Write-Host "============================================================" -ForegroundColor Cyan
  $lines = @(& powershell.exe -NoLogo -NoProfile -ExecutionPolicy Bypass -File $FilePath 2>&1 | ForEach-Object { "$($_)"; Write-Host "$($_)" })
  $code = $LASTEXITCODE
  $status = if ($code -eq 0) { 'PASS' } else { 'FAIL' }
  $script:PhaseResults += [pscustomobject]@{ Phase=$Title; Status=$status; ExitCode=$code }
  Write-Host "نتیجه مرحله: $status (exit code $code)" -ForegroundColor $(if ($code -eq 0) { 'Green' } else { 'Red' })
}

try {
  # Embedded source: FinalAudit
  $b64_FinalAudit = @'

'@
  $file_FinalAudit = Join-Path $tempRoot 'test-final-audit.ps1'
  $bytes_FinalAudit = [Convert]::FromBase64String(($b64_FinalAudit -replace '\s',''))
  if ($bytes_FinalAudit.Length -lt 3 -or $bytes_FinalAudit[0] -ne 0xEF -or $bytes_FinalAudit[1] -ne 0xBB -or $bytes_FinalAudit[2] -ne 0xBF) { $bytes_FinalAudit = [byte[]](@(0xEF,0xBB,0xBF) + $bytes_FinalAudit) }
  [IO.File]::WriteAllBytes($file_FinalAudit, $bytes_FinalAudit)
  # Embedded source: SafeWorkflows
  $b64_SafeWorkflows = @'

'@
  $file_SafeWorkflows = Join-Path $tempRoot 'test-workflows.ps1'
  $bytes_SafeWorkflows = [Convert]::FromBase64String(($b64_SafeWorkflows -replace '\s',''))
  if ($bytes_SafeWorkflows.Length -lt 3 -or $bytes_SafeWorkflows[0] -ne 0xEF -or $bytes_SafeWorkflows[1] -ne 0xBB -or $bytes_SafeWorkflows[2] -ne 0xBF) { $bytes_SafeWorkflows = [byte[]](@(0xEF,0xBB,0xBF) + $bytes_SafeWorkflows) }
  [IO.File]::WriteAllBytes($file_SafeWorkflows, $bytes_SafeWorkflows)
  # Embedded source: FullWorkflows
  $b64_FullWorkflows = @'

'@
  $file_FullWorkflows = Join-Path $tempRoot 'test-full-workflows.ps1'
  $bytes_FullWorkflows = [Convert]::FromBase64String(($b64_FullWorkflows -replace '\s',''))
  if ($bytes_FullWorkflows.Length -lt 3 -or $bytes_FullWorkflows[0] -ne 0xEF -or $bytes_FullWorkflows[1] -ne 0xBB -or $bytes_FullWorkflows[2] -ne 0xBF) { $bytes_FullWorkflows = [byte[]](@(0xEF,0xBB,0xBF) + $bytes_FullWorkflows) }
  [IO.File]::WriteAllBytes($file_FullWorkflows, $bytes_FullWorkflows)

  # Run business service integration first; it creates and drops only a uniquely named test DB.
  Run-Phase 'گردش‌کارهای کسب‌وکار روی دیتابیس موقت' $file_FullWorkflows

  # This phase uses existing test accounts and fixtures against the configured local API.
  # Its favorite test is reversible and preserves an already-existing favorite.
  Run-Phase 'API، نشست‌ها، نقش‌ها و دسترسی‌ها (تست‌های امن موجود)' $file_SafeWorkflows

  # This phase runs validation/lint/smoke checks and temporarily stops/restores frontend for build.
  Run-Phase 'ممیزی نهایی، TypeScript، lint و build' $file_FinalAudit

  # Preserve and run the previously used authorization audit if the user already has it in project root.
  $existingAccess = Join-Path $root 'test-access.ps1'
  if (Test-Path $existingAccess) {
    Run-Phase 'ممیزی تکمیلی دسترسی نقش‌ها (test-access.ps1 موجود)' $existingAccess
  } else {
    Write-Host "`n[SKIP] فایل test-access.ps1 در پوشه پروژه پیدا نشد؛ این ممیزی جداگانه اجرا نشد." -ForegroundColor Yellow
    $script:PhaseResults += [pscustomobject]@{ Phase='ممیزی تکمیلی دسترسی نقش‌ها'; Status='SKIP'; ExitCode=$null }
  }
}
finally {
  Remove-Item $tempRoot -Recurse -Force -ErrorAction SilentlyContinue
}

Write-Host "`n============================================================" -ForegroundColor White
Write-Host 'خلاصه نهایی تست‌های هشتی' -ForegroundColor White
Write-Host "============================================================" -ForegroundColor White
$script:PhaseResults | ForEach-Object {
  $color = if ($_.Status -eq 'PASS') { 'Green' } elseif ($_.Status -eq 'FAIL') { 'Red' } else { 'Yellow' }
  Write-Host ("[{0}] {1}{2}" -f $_.Status, $_.Phase, $(if ($null -ne $_.ExitCode) { " (exit=$($_.ExitCode))" } else { '' })) -ForegroundColor $color
}
$failed = @($script:PhaseResults | Where-Object Status -eq 'FAIL').Count
$skipped = @($script:PhaseResults | Where-Object Status -eq 'SKIP').Count
$passed = @($script:PhaseResults | Where-Object Status -eq 'PASS').Count
Write-Host ("`nمراحل موفق: {0} | مراحل ناموفق: {1} | مراحل ردشده: {2}" -f $passed,$failed,$skipped) -ForegroundColor White
if ($failed -gt 0) { exit 1 }
exit 0
